// Test sort logic for dates in string format
void main() {
  final dates = ['2026-09-20', '2026-09-10', '2026-09-15', ''];
  dates.sort((a, b) {
    {
      final x = a;
      final y = b;
      if (x.isEmpty != y.isEmpty) return x.isEmpty ? 1 : -1;
      final nx = num.tryParse(x), ny = num.tryParse(y);
      final c = (nx != null && ny != null) ? nx.compareTo(ny) : x.compareTo(y);
      if (c != 0) return c;
    }
    return 0;
  });
  print('Sorted: $dates');
  // Expected: [2026-09-10, 2026-09-15, 2026-09-20, ] - soonest first
}
EOF
